let nap = true;
let inspectwin = false;
let devmstate = "normal";
let pintura = false;

document.addEventListener('keydown', function (e) {
            if (e.key === 'F3' || e.keyCode == 114) {

                   e.cancelBubble = true;
                    e.cancelable = true;
                    e.stopPropagation();
                    e.preventDefault();
                    e.returnValue = false;

                if (devmstate == "normal") {
                    floatdevmode();
                    devmstate = "float"
                } else {
                    devmode();
                    devmstate = "normal";
                }
                
            }
    
            if (e.key === 'F5' || e.keyCode == 116) {

                   e.cancelBubble = true;
                    e.cancelable = true;
                    e.stopPropagation();
                    e.preventDefault();
                    e.returnValue = false;

                if (!inspectwin) {
                    inspectwin = true;
                    state();
                    widget("State");
                } else {
                    inspectwin = false;
                    remove("State");
                }
            }
    
            if (e.key === 'F4' || e.keyCode == 115) {

                   e.cancelBubble = true;
                    e.cancelable = true;
                    e.stopPropagation();
                    e.preventDefault();
                    e.returnValue = false;

                if (!nap) {
                    snap();
                    nap = true;
                } else {
                    nosnap();
                    nap = false;
                }
            }
  
            if (e.key === 'F6' || e.keyCode == 117) {

                   e.cancelBubble = true;
                    e.cancelable = true;
                    e.stopPropagation();
                    e.preventDefault();
                    e.returnValue = false;

                if (!pintura) {
                    pintura = true;
                    draw();
                } else {
                    pintura = false;
                    removedraw();
                }
            }

  
  
});


